index fea2056..e4eb291 100644
--- a/src/core/trailers.ts
+++ b/src/core/trailers.ts
@@ -1,7 +1,37 @@
 import type { Provenance } from "./grade.ts";

-export const provenanceOf = (trailers: ReadonlyMap<string, string>): Provenance => {
+export interface CommitMetadata {
+  // Signature verification if available (extension point for signature schemes)
+  signature?: { valid: boolean; keyId?: string };
+  committer: { name: string; email: string };
+  knownKeys?: ReadonlySet<string>;
+}
+
+export const provenanceOf = (
+  trailers: ReadonlyMap<string, string>,
+  metadata: CommitMetadata
+): Provenance => {
+  // Security: never trust self-asserted provenance trailers. Author and Provenance
+  // fields are commit message strings that anyone can forge. Only cryptographic proof
+  // (signatures) counts as verification. Without it, default to unknown and let the
+  // system demote records that cannot be established as authored.
+
+  // Accept "authored" only if cryptographically verified via signature
+  if (
+    metadata.signature?.valid &&
+    metadata.signature.keyId &&
+    metadata.knownKeys?.has(metadata.signature.keyId)
+  ) {
+    return "authored";
+  }
+
+  // "inherited" and "reconstructed" values are rejected if self-asserted in commit
+  // messages (trailers can be fabricated). These should only come from verifiable
+  // git history analysis, implemented separately.
   const raw = trailers.get("Provenance");
-  if (raw === "authored" || raw === "inherited" || raw === "reconstructed") return raw;
+  if (raw === "inherited" || raw === "reconstructed") {
+    return "unknown";
+  }
+
   return "unknown";
 };
